sys_script_fix.script:
var demandFieldGr = new GlideRecord("sys_dictionary");
demandFieldGr.addQuery("name","rm_story");
demandFieldGr.addQuery("element", "demand");
demandFieldGr.query();
if (demandFieldGr.next()){
	demandFieldGr.setValue("read_only",true);
	demandFieldGr.setWorkflow(false);
	demandFieldGr.update();
}
